import React, { useState } from "react";
import { Link } from "react-router-dom";

const ForgotPassword = (props) => {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [emailSent, setEmailSent] = useState(false);
  const host = "http://localhost:5000";

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await fetch(`${host}/api/auth/forgot-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email }),
      });

      const result = await response.json();
      
      if (response.ok) {
        setEmailSent(true);
        props.showAlert("Password reset email sent successfully", "success");
      } else {
        props.showAlert(result.message || "Failed to send reset email", "danger");
      }
    } catch (error) {
      console.error('Error sending reset email:', error);
      props.showAlert("Error sending reset email", "danger");
    } finally {
      setLoading(false);
    }
  };

  const resendEmail = () => {
    setEmailSent(false);
    handleSubmit({ preventDefault: () => {} });
  };

  if (emailSent) {
    return (
      <div className="container mt-5">
        <div className="row justify-content-center">
          <div className="col-md-6">
            <div className="card">
              <div className="card-body text-center">
                <div className="mb-4">
                  <i className="fas fa-envelope fa-4x text-success"></i>
                </div>
                <h3 className="card-title">Check Your Email</h3>
                <p className="card-text">
                  We've sent a password reset link to <strong>{email}</strong>
                </p>
                <p className="text-muted">
                  Didn't receive the email? Check your spam folder or try again.
                </p>
                <div className="d-grid gap-2">
                  <button 
                    className="btn btn-primary"
                    onClick={resendEmail}
                    disabled={loading}
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                        Resending...
                      </>
                    ) : (
                      "Resend Email"
                    )}
                  </button>
                  <Link to="/login" className="btn btn-outline-secondary">
                    Back to Login
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container mt-5">
      <div className="row justify-content-center">
        <div className="col-md-6">
          <div className="card">
            <div className="card-header text-center">
              <h2 className="mb-0">
                <i className="fas fa-key me-2"></i>Forgot Password
              </h2>
            </div>
            <div className="card-body">
              <p className="text-muted text-center mb-4">
                Enter your email address and we'll send you a link to reset your password.
              </p>
              
              <form onSubmit={handleSubmit}>
                <div className="mb-3">
                  <label htmlFor="email" className="form-label">
                    <i className="fas fa-envelope me-2"></i>Email Address
                  </label>
                  <input
                    type="email"
                    className="form-control"
                    id="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="Enter your email address"
                    required
                  />
                </div>

                <div className="d-grid">
                  <button 
                    type="submit" 
                    className="btn btn-primary"
                    disabled={loading || !email}
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                        Sending...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-paper-plane me-2"></i>Send Reset Link
                      </>
                    )}
                  </button>
                </div>
              </form>

              <div className="text-center mt-3">
                <Link to="/login" className="text-decoration-none">
                  <i className="fas fa-arrow-left me-1"></i>Back to Login
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ForgotPassword;
